const std=@import("std");
const l=@import("lexer.zig");
const p=@import("parser.zig");
pub const Opcode=enum { PUSH,POP,LOADG,STOREG,LOADL,STOREL,LOADA,STOREA,ADD,SUB,MUL,DIV,MOD,LT,LE,GT,GE,EQ,NE,NEG,NOT,JUMP,JUMPF,JUMPT,CALL,ENTER,RET,RETV,READ,PRINT,HALT };
pub const Instruction=struct { op:Opcode,a:i64=0,b:i64=0,position:l.Position,callee:?*p.Declaration=null };
pub const Block=struct { first:usize,last:usize,successors:[]const usize };
pub const Unit=struct { name:[]const u8,declaration:?*p.Declaration=null,before:[]const Instruction=&.{},after:[]const Instruction=&.{},slots:[]const *p.Declaration=&.{},before_start:usize=0,after_start:usize=0,stack_depth:i64=0,blocks:[]const Block=&.{},recursive:bool=false };
pub fn jump(op:Opcode) bool { return op==.JUMP or op==.JUMPF or op==.JUMPT; }
pub fn conditional(op:Opcode) bool { return op==.JUMPF or op==.JUMPT; }
pub fn transfer(op:Opcode) bool { return op==.JUMP or op==.RET or op==.RETV or op==.HALT; }
pub fn operands(op:Opcode) usize { return switch(op) {.PUSH,.LOADG,.STOREG,.LOADL,.STOREL,.JUMP,.JUMPF,.JUMPT,.ENTER,.PRINT=>1,.LOADA,.STOREA,.CALL=>2,else=>0}; }
pub fn spelling(instruction:Instruction) []const u8 { return switch(operands(instruction.op)) {0=>@tagName(instruction.op),1=>l.fmt("{s} {d}",.{@tagName(instruction.op),instruction.a}),else=>l.fmt("{s} {d} {d}",.{@tagName(instruction.op),instruction.a,instruction.b})}; }
pub fn arithmetic(op:[]const u8) Opcode { const symbols=[_][]const u8{"+","-","*","/","%","<","<=",">",">=","==","!="}; const ops=[_]Opcode{.ADD,.SUB,.MUL,.DIV,.MOD,.LT,.LE,.GT,.GE,.EQ,.NE}; for(symbols,ops) |s,o| if(l.eq(op,s)) return o; unreachable; }
const Loop=struct { breaks:std.ArrayList(usize)=.empty,continues:std.ArrayList(usize)=.empty };
const Generator=struct {
    code:std.ArrayList(Instruction)=.empty,loops:std.ArrayList(Loop)=.empty,
    fn emit(self:*Generator,op:Opcode,a:i64,b:i64,pos:l.Position) usize { const i=self.code.items.len; l.append(Instruction,&self.code,.{.op=op,.a=a,.b=b,.position=pos}); return i; }
    fn patch(self:*Generator,at:usize,target:usize) void { self.code.items[at].a=@intCast(target); }
    fn expression(self:*Generator,n:*p.Node) void {
        switch(n.kind) {
            .literal=>{ _=self.emit(.PUSH,n.value,0,n.position); },.read=>{ _=self.emit(.READ,0,0,n.position); },
            .variable=>{ const decl=n.target.?; _=self.emit(if(decl.global) .LOADG else .LOADL,@intCast(if(decl.global) decl.address else decl.slot),0,n.position); },
            .index=>{ self.expression(n.children[0]); const decl=n.target.?; _=self.emit(.LOADA,@intCast(decl.address),@intCast(decl.size),n.position); },
            .call=>{ for(n.children) |arg| self.expression(arg); const i=self.emit(.CALL,0,@intCast(n.children.len),n.position); self.code.items[i].callee=n.target; },
            .unary=>{ self.expression(n.children[0]); _=self.emit(if(l.eq(n.op,"-")) .NEG else .NOT,0,0,n.position); },
            .binary=>{
                self.expression(n.children[0]); if(l.eq(n.op,"&&") or l.eq(n.op,"||")) { const or_op=l.eq(n.op,"||"); const first=self.emit(if(or_op) .JUMPT else .JUMPF,0,0,n.position); self.expression(n.children[1]); const end=self.emit(.JUMP,0,0,n.position); self.patch(first,self.code.items.len); _=self.emit(.PUSH,@intFromBool(or_op),0,n.position); self.patch(end,self.code.items.len); }
                else { self.expression(n.children[1]); _=self.emit(arithmetic(n.op),0,0,n.position); }
            },else=>unreachable,
        }
    }
    fn statement(self:*Generator,n:*p.Node) void {
        switch(n.kind) {
            .empty=>{},.block=>for(n.children) |statement_node| { self.statement(statement_node); },
            .declaration=>{ const decl=n.declaration.?; if(decl.initializer) |initializer| self.expression(initializer) else { _=self.emit(.PUSH,0,0,decl.name_position); } _=self.emit(.STOREL,@intCast(decl.slot),0,decl.name_position); },
            .assignment=>{ const decl=n.target.?; for(n.children) |expr| self.expression(expr); if(n.children.len==2) { _=self.emit(.STOREA,@intCast(decl.address),@intCast(decl.size),n.position); } else { _=self.emit(if(decl.global) .STOREG else .STOREL,@intCast(if(decl.global) decl.address else decl.slot),0,n.position); } },
            .call_stmt=>{ const expr=n.children[0]; self.expression(expr); if(expr.kind==.read or expr.typ!=.void) _=self.emit(.POP,0,0,n.position); },
            .print_stmt=>{ for(n.children) |expr| self.expression(expr); _=self.emit(.PRINT,@intCast(n.children.len),0,n.position); },
            .return_stmt=>{ if(n.children.len>0) self.expression(n.children[0]); _=self.emit(if(n.children.len==0) .RET else .RETV,0,0,n.position); },
            .if_stmt=>{ self.expression(n.children[0]); const branch=self.emit(.JUMPF,0,0,n.position); self.statement(n.children[1]); if(n.children.len==3) { const end=self.emit(.JUMP,0,0,n.position); self.patch(branch,self.code.items.len); self.statement(n.children[2]); self.patch(end,self.code.items.len); } else self.patch(branch,self.code.items.len); },
            .while_stmt,.for_stmt=>{
                const for_loop=n.kind==.for_stmt; if(for_loop) self.statement(n.children[0]); const head=self.code.items.len; const condition=n.children[if(for_loop) @as(usize,1) else 0]; var exit:?usize=null;
                if(condition.kind!=.empty) { self.expression(condition); exit=self.emit(.JUMPF,0,0,n.position); }
                l.append(Loop,&self.loops,.{}); self.statement(n.children[if(for_loop) @as(usize,3) else 1]); const continuation=if(for_loop) self.code.items.len else head; if(for_loop) self.statement(n.children[2]); _=self.emit(.JUMP,@intCast(head),0,n.position); const end=self.code.items.len; if(exit) |i| self.patch(i,end); const loop=self.loops.pop().?; for(loop.breaks.items) |i| self.patch(i,end); for(loop.continues.items) |i| self.patch(i,continuation);
            },
            .break_stmt,.continue_stmt=>{ const i=self.emit(.JUMP,0,0,n.position); const loop=&self.loops.items[self.loops.items.len-1]; l.append(usize,if(n.kind==.break_stmt) &loop.breaks else &loop.continues,i); },
            else=>unreachable,
        }
    }
};
fn localDeclarations(n:*p.Node,out:*std.ArrayList(*p.Declaration)) void { if(n.kind==.declaration) l.append(*p.Declaration,out,n.declaration.?); for(n.children) |child| localDeclarations(child,out); }
pub fn generate(declarations:[]const *p.Declaration,main:*p.Declaration) []Unit {
    var units:std.ArrayList(Unit)=.empty; l.append(Unit,&units,.{.name="<init>"}); var address:usize=0;
    for(declarations) |decl| { if(!decl.function) { decl.address=address; address+=decl.size; } else if(decl.reachable) { decl.unit=units.items.len; l.append(Unit,&units,.{.name=decl.name,.declaration=decl}); } }
    var initialization:Generator=.{}; for(declarations) |decl| if(!decl.function) { if(decl.initializer) |initializer| { initialization.expression(initializer); _=initialization.emit(.STOREG,@intCast(decl.address),0,decl.name_position); } }; const call=initialization.emit(.CALL,0,0,main.name_position); initialization.code.items[call].callee=main; _=initialization.emit(.HALT,0,0,main.name_position); units.items[0].before=initialization.code.items;
    for(units.items[1..]) |*unit| { const decl=unit.declaration.?; var locals:std.ArrayList(*p.Declaration)=.empty; localDeclarations(decl.body.?,&locals); std.mem.sort(*p.Declaration,locals.items,{},struct { fn less(_:void,a:*p.Declaration,b:*p.Declaration) bool { return l.before(a.name_position,b.name_position); } }.less); var slots:std.ArrayList(*p.Declaration)=.empty; for(decl.parameters) |param| l.append(*p.Declaration,&slots,param); for(locals.items) |local| l.append(*p.Declaration,&slots,local); for(slots.items,0..) |variable,i| variable.slot=i; unit.slots=slots.items;
        var generator:Generator=.{}; _=generator.emit(.ENTER,@intCast(slots.items.len),0,decl.name_position); generator.statement(decl.body.?); if(decl.typ==.void) _=generator.emit(.RET,0,0,decl.body.?.closing); unit.before=generator.code.items;
    }
    return units.items;
}
pub fn flatten(units:[]Unit,after:bool) []const Instruction {
    var address:usize=0; for(units) |*unit| { if(after) unit.after_start=address else unit.before_start=address; address+=(if(after) unit.after else unit.before).len; }
    var out:std.ArrayList(Instruction)=.empty;
    for(units) |unit| { const start=if(after) unit.after_start else unit.before_start; for(if(after) unit.after else unit.before) |original| { var instruction=original; if(jump(instruction.op)) instruction.a+=@intCast(start); if(instruction.callee) |callee| instruction.a=@intCast(if(after) units[callee.unit].after_start else units[callee.unit].before_start); l.append(Instruction,&out,instruction); } }
    return out.items;
}

const std=@import("std");
pub var allocator:std.mem.Allocator=undefined;
pub fn alloc(comptime T:type,n:usize) []T { return allocator.alloc(T,n) catch @panic("allocation failed"); }
pub fn create(comptime T:type,v:T) *T { const p=allocator.create(T) catch @panic("allocation failed"); p.*=v; return p; }
pub fn append(comptime T:type,a:*std.ArrayList(T),v:T) void { a.append(allocator,v) catch @panic("allocation failed"); }
pub fn fmt(comptime s:[]const u8,a:anytype) []const u8 { return std.fmt.allocPrint(allocator,s,a) catch @panic("allocation failed"); }
pub fn eq(a:[]const u8,b:[]const u8) bool { return std.mem.eql(u8,a,b); }
pub fn spaces(n:usize) []const u8 { const s=alloc(u8,n); @memset(s,' '); return s; }
pub const Text=struct { data:std.ArrayList(u8)=.empty,pub fn put(self:*Text,comptime s:[]const u8,a:anytype) void { self.data.appendSlice(allocator,fmt(s,a)) catch @panic("allocation failed"); } pub fn line(self:*Text,comptime s:[]const u8,a:anytype) void { self.put(s,a); self.put("\n",.{}); } };
pub const Position=struct { line:usize,column:usize,pub fn str(self:Position) []const u8 { return fmt("{d}:{d}",.{self.line,self.column}); } };
pub fn before(a:Position,b:Position) bool { return a.line<b.line or (a.line==b.line and a.column<b.column); }
pub const Failure=struct { kind:[]const u8,position:Position,message:[]const u8 };
pub const Token=struct { kind:enum{identifier,keyword,integer,symbol,end},text:[]const u8,position:Position };
pub const Result=struct { tokens:[]const Token,failure:?Failure=null };
pub fn scan(source:[]const u8,first_line:usize) Result {
    var tokens:std.ArrayList(Token)=.empty; var at:usize=0; var line=first_line; var column:usize=1; var failure:?Failure=null;
    while(at<source.len) {
        if(source[at]==' ' or source[at]=='\n') { if(source[at]=='\n') { line+=1; column=1; } else column+=1; at+=1; continue; }
        const start=at; const pos=Position{.line=line,.column=column}; var kind:@FieldType(Token,"kind")=.symbol;
        if(std.mem.startsWith(u8,source[at..],"//")) { while(at<source.len and source[at]!='\n') : (at+=1) { column+=1; } continue; }
        if(std.mem.startsWith(u8,source[at..],"/*")) { const end=std.mem.indexOf(u8,source[at+2..],"*/") orelse { failure=.{.kind="lexical",.position=pos,.message="unterminated comment"}; break; }; const stop=at+2+end+2; while(at<stop) : (at+=1) { if(source[at]=='\n') { line+=1; column=1; } else column+=1; } continue; }
        if(std.ascii.isAlphabetic(source[at]) or source[at]=='_') { at+=1; while(at<source.len and (std.ascii.isAlphanumeric(source[at]) or source[at]=='_')) : (at+=1) {} kind=.identifier; for([_][]const u8{"int","bool","void","true","false","if","else","while","for","break","continue","return","print","read"}) |keyword| if(eq(source[start..at],keyword)) { kind=.keyword; break; }; }
        else if(std.ascii.isDigit(source[at])) { at+=1; while(at<source.len and std.ascii.isDigit(source[at])) : (at+=1) {} kind=.integer; const n=std.fmt.parseInt(i64,source[start..at],10) catch std.math.maxInt(i64); if(n>2147483647) { failure=.{.kind="lexical",.position=pos,.message="integer literal too large"}; break; } }
        else { var pair=false; if(at+1<source.len) for([_][]const u8{"<=",">=","==","!=","&&","||"}) |symbol| if(eq(source[at..at+2],symbol)) { pair=true; break; }; if(pair) at+=2 else if(std.mem.indexOfScalar(u8,"+-*/%<>=!(){}[],;",source[at])!=null) at+=1 else { failure=.{.kind="lexical",.position=pos,.message=fmt("unexpected character '{c}'",.{source[at]})}; break; } }
        append(Token,&tokens,.{.kind=kind,.text=source[start..at],.position=pos}); column+=at-start;
    }
    const trimmed=std.mem.trimEnd(u8,source,"\n"); const last_start=if(std.mem.lastIndexOfScalar(u8,trimmed,'\n')) |i| i+1 else 0; var last_line=first_line; for(trimmed) |c| if(c=='\n') { last_line+=1; };
    append(Token,&tokens,.{.kind=.end,.text="",.position=.{.line=last_line,.column=trimmed.len-last_start+1}}); return .{.tokens=tokens.items,.failure=failure};
}
pub fn read(io:std.Io,path:[]const u8) ![]const u8 { return std.Io.Dir.cwd().readFileAlloc(io,path,allocator,.unlimited); }
pub fn write(io:std.Io,name:[]const u8,text:Text) !void { try std.Io.Dir.cwd().writeFile(io,.{.sub_path=fmt("output/{s}",.{name}),.data=text.data.items}); }

const std=@import("std");
const l=@import("lexer.zig");
const p=@import("parser.zig");
const semantic=@import("semantic.zig");
const cg=@import("codegen.zig");
const vm=@import("vm.zig");
const rules=[_][]const u8{"const-jump","not-compare","not-jump","invert-branch","thread","jump-next","unreachable"};
fn inRange(n:i64) bool { return n>=-2147483648 and n<=2147483647; }
fn literal(n:*p.Node,value:i64) *p.Node { const out=p.node(.literal,n.position,&.{}); out.typ=n.typ; out.value=value; return out; }
fn foldExpression(n:*p.Node,count:*usize) *p.Node {
    for(n.children) |*child| child.*=foldExpression(child.*,count);
    if(n.kind==.unary and n.children[0].kind==.literal) { const value=if(l.eq(n.op,"-")) -n.children[0].value else @as(i64,@intFromBool(n.children[0].value==0)); if(inRange(value)) { count.*+=1; return literal(n,value); } }
    if(n.kind!=.binary) return n;
    const a=n.children[0]; const b=n.children[1]; const op=n.op;
    if(a.kind==.literal and b.kind==.literal) {
        var result:?i64=null; const x=a.value; const y=b.value;
        if(l.eq(op,"+")) result=x+y else if(l.eq(op,"-")) result=x-y else if(l.eq(op,"*")) result=x*y
        else if(l.eq(op,"/")) { if(y!=0) result=@divTrunc(x,y); }
        else if(l.eq(op,"%")) { if(y!=0) result=@rem(x,y); }
        else result=@intFromBool(if(l.eq(op,"<")) x<y else if(l.eq(op,"<=")) x<=y else if(l.eq(op,">")) x>y else if(l.eq(op,">=")) x>=y else if(l.eq(op,"==")) x==y else if(l.eq(op,"!=")) x!=y else if(l.eq(op,"&&")) x!=0 and y!=0 else x!=0 or y!=0);
        if(result) |value| if(inRange(value)) { count.*+=1; return literal(n,value); };
    }
    if(a.kind==.literal and ((l.eq(op,"&&") and a.value==0) or (l.eq(op,"||") and a.value!=0))) { count.*+=1; return literal(n,a.value); }
    if(a.kind==.literal and ((l.eq(op,"&&") and a.value!=0) or (l.eq(op,"||") and a.value==0) or (l.eq(op,"+") and a.value==0) or (l.eq(op,"*") and a.value==1))) { count.*+=1; return b; }
    if(b.kind==.literal and (((l.eq(op,"+") or l.eq(op,"-")) and b.value==0) or ((l.eq(op,"*") or l.eq(op,"/")) and b.value==1) or (l.eq(op,"&&") and b.value!=0) or (l.eq(op,"||") and b.value==0))) { count.*+=1; return a; }
    return n;
}
fn foldStatement(n:*p.Node,count:*usize) *p.Node {
    switch(n.kind) {
        .declaration=>{ const decl=n.declaration.?; if(decl.initializer) |initializer| decl.initializer=foldExpression(initializer,count); },
        .assignment,.print_stmt,.call_stmt,.return_stmt=>for(n.children) |*child| { child.*=foldExpression(child.*,count); },
        .if_stmt=>{ n.children[0]=foldExpression(n.children[0],count); if(n.children[0].kind==.literal) { count.*+=1; if(n.children[0].value!=0) return foldStatement(n.children[1],count); if(n.children.len==3) return foldStatement(n.children[2],count); return p.node(.empty,n.position,&.{}); } n.children[1]=foldStatement(n.children[1],count); if(n.children.len==3) n.children[2]=foldStatement(n.children[2],count); },
        .while_stmt=>{ n.children[0]=foldExpression(n.children[0],count); if(n.children[0].kind==.literal and n.children[0].value==0) { count.*+=1; return p.node(.empty,n.position,&.{}); } n.children[1]=foldStatement(n.children[1],count); },
        .for_stmt=>{ n.children[0]=foldStatement(n.children[0],count); if(n.children[1].kind!=.empty) n.children[1]=foldExpression(n.children[1],count); n.children[2]=foldStatement(n.children[2],count); n.children[3]=foldStatement(n.children[3],count); },
        .block=>for(n.children) |*child| { child.*=foldStatement(child.*,count); },else=>{},
    }
    return n;
}
fn inverse(op:cg.Opcode) cg.Opcode { return if(op==.JUMPF) .JUMPT else .JUMPF; }
fn negated(op:cg.Opcode) ?cg.Opcode { return switch(op) {.LT=>.GE,.LE=>.GT,.GT=>.LE,.GE=>.LT,.EQ=>.NE,.NE=>.EQ,else=>null}; }
fn jumps(op:cg.Opcode,n:i64) bool { return (op==.JUMPF and n==0) or (op==.JUMPT and n!=0); }
fn delete(code:*std.ArrayList(cg.Instruction),at:usize) void { _=code.orderedRemove(at); for(code.items) |*instruction| if(cg.jump(instruction.op) and instruction.a>@as(i64,@intCast(at))) { instruction.a-=1; }; }
fn optimize(original:[]const cg.Instruction,counts:*[7]usize) []const cg.Instruction {
    var code:std.ArrayList(cg.Instruction)=.empty; for(original) |instruction| l.append(cg.Instruction,&code,instruction);
    outer: while(true) {
        const targets=l.alloc(bool,code.items.len+1); @memset(targets,false); for(code.items) |instruction| if(cg.jump(instruction.op)) { targets[@intCast(instruction.a)]=true; };
        for(0..code.items.len) |i| {
            const a=code.items[i]; const next=i+1<code.items.len; const b:cg.Instruction=if(next) code.items[i+1] else a; const free=next and !targets[i+1]; var rule:?usize=null;
            if(a.op==.PUSH and free and cg.conditional(b.op)) { if(jumps(b.op,a.a)) { code.items[i]=.{.op=.JUMP,.a=b.a,.position=b.position}; delete(&code,i+1); } else { delete(&code,i+1); delete(&code,i); } rule=0; }
            else if(free and b.op==.NOT and negated(a.op)!=null) { code.items[i].op=negated(a.op).?; delete(&code,i+1); rule=1; }
            else if(a.op==.NOT and free and cg.conditional(b.op)) { code.items[i]=.{.op=inverse(b.op),.a=b.a,.position=b.position}; delete(&code,i+1); rule=2; }
            else if(cg.conditional(a.op) and a.a==@as(i64,@intCast(i+2)) and free and b.op==.JUMP) { code.items[i].op=inverse(a.op); code.items[i].a=b.a; delete(&code,i+1); rule=3; }
            else {
                if(cg.jump(a.op) and a.a<@as(i64,@intCast(code.items.len))) { const target:usize=@intCast(a.a); const at=code.items[target]; var new:?i64=null; if(at.op==.JUMP) new=at.a else if(at.op==.PUSH and target+1<code.items.len and cg.conditional(code.items[target+1].op)) { const branch=code.items[target+1]; new=if(jumps(branch.op,at.a)) branch.a else @intCast(target+2); } if(new!=null and new.?!=a.a) { code.items[i].a=new.?; rule=4; } }
                if(rule==null and cg.jump(a.op) and a.a==@as(i64,@intCast(i+1))) { if(a.op==.JUMP) delete(&code,i) else code.items[i]=.{.op=.POP,.position=a.position}; rule=5; }
                if(rule==null and cg.transfer(a.op) and free) { delete(&code,i+1); rule=6; }
            }
            if(rule) |r| { counts[r]+=1; continue :outer; }
        }
        break;
    }
    return code.items;
}
fn nextIndices(code:[]const cg.Instruction,at:usize) []const usize { var out:std.ArrayList(usize)=.empty; const instruction=code[at]; if(!cg.transfer(instruction.op) and at+1<code.len) l.append(usize,&out,at+1); if(cg.jump(instruction.op) and instruction.a<@as(i64,@intCast(code.len))) { const target:usize=@intCast(instruction.a); var duplicate=false; for(out.items) |i| if(i==target) { duplicate=true; break; }; if(!duplicate) l.append(usize,&out,target); } return out.items; }
fn effect(instruction:cg.Instruction) i64 { return switch(instruction.op) {.PUSH,.LOADG,.LOADL,.READ=>1,.POP,.STOREG,.STOREL,.JUMPF,.JUMPT,.RETV,.ADD,.SUB,.MUL,.DIV,.MOD,.LT,.LE,.GT,.GE,.EQ,.NE=>-1,.STOREA=>-2,.CALL=>-instruction.b+@as(i64,@intFromBool(instruction.callee.?.typ!=.void)),.PRINT=>-instruction.a,else=>0}; }
fn flow(unit:*cg.Unit) void {
    const code=unit.after; const leaders=l.alloc(bool,code.len); @memset(leaders,false); leaders[0]=true;
    for(code,0..) |instruction,i| { if(cg.jump(instruction.op) and instruction.a<@as(i64,@intCast(code.len))) leaders[@intCast(instruction.a)]=true; if((cg.jump(instruction.op) or cg.transfer(instruction.op)) and i+1<code.len) leaders[i+1]=true; }
    var starts:std.ArrayList(usize)=.empty; for(leaders,0..) |yes,i| if(yes) l.append(usize,&starts,i); const block_for=l.alloc(usize,code.len); for(starts.items,0..) |first,k| { const end=if(k+1<starts.items.len) starts.items[k+1] else code.len; for(first..end) |i| block_for[i]=k; }
